    sector = rng.choice(sectors)
    delta_k = rng.randint(2, 20)
    opts = [
        {
            'content': 'La función de producción exhibe rendimientos constantes a escala global coexistiendo con rendimientos marginales decrecientes en cada factor individual ($F_{KK} < 0$).',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': 'La productividad marginal del capital $\\partial F / \\partial K$ es estrictamente decreciente conforme se eleva la intensidad de capital $r = K/L$.',
            'is_correct': True,
            'distractor_id': None
        },
        {
            'content': f'Porque la función tiene rendimientos constantes a escala, el producto marginal del capital debe ser constante cuando se acumulan {delta_k} veces más capital manteniendo el trabajo fijo.',
            'is_correct': False,
            'distractor_id': 'D-C05-01',
            'error_rationale': 'Confunde la homogeneidad de grado 1 de la función conjunta con el comportamiento de la derivada parcial individual; los rendimientos constantes a escala coexisten con rendimientos marginales decrecientes en cada factor.'
        },
        {
            'content': f'Multiplicar únicamente el stock de capital físico por {delta_k} manteniendo inalterado el trabajo genera exactamente {delta_k} veces más producto total en la economía.',
            'is_correct': False,
            'distractor_id': 'D-C05-01',
            'error_rationale': 'Para multiplicar el producto agregado bajo rendimientos constantes a escala se requiere multiplicar todos los factores simultáneamente; incrementar únicamente el capital produce un aumento subproporcional.'
        }
    ]
    return {
        'vars': {'sector': sector, 'delta_k': delta_k},
        'options': opts,
        'distractors': []
    }

